


export type DeliveryRateCallbackConnectionCheck = { /** RFC3339 timestamp. Format: date-time. */ "checked_at": string; "delivery_rate_callback_id": string; "delivery_rate_callback_revision_id": string; /** Why the callback connection check failed and the action that can make the next check succeed. - `authentication_or_http_error`: Return a 2xx status for a signed request. A 401 usually means the wrong secret or a body parsed before verification. - `blocked_target`: Use a public HTTPS callback target allowed by Flint's outbound network policy. - `connection_error`: Restore network connectivity to the callback host, then test again. - `dns_error`: Fix the callback hostname or its DNS records, then test again. - `invalid_response`: Return a 2xx application/json response within maximum_response_bytes. For a test delivery, the body must also follow the callback response rules. Then test again. - `request_error`: Flint couldn't complete the request for another reason. Check the URL and your server logs, then test again. - `timeout`: Acknowledge the callback within its configured timeout, then test again. - `tls_error`: Fix the callback certificate and TLS configuration, then test again. */ "failure_category"?: "authentication_or_http_error" | "blocked_target" | "connection_error" | "dns_error" | "invalid_response" | "request_error" | "timeout" | "tls_error" | (string & {}); "http_status_code"?: number; "key_id": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "latency_milliseconds": string; "status": "succeeded" | "failed" | (string & {}); };
